"""Collect delivery, validators, real-browser samples and verification evidence."""
import json,hashlib,re
from pathlib import Path
O=Path('.work/toy-character/display2')
def read(p):return json.loads((O/p).read_text())
c=read('final/compression.json');g=read('geometry-verification.json');web=read('web-metrics.json');neck=read('neck-edit.json');hair=read('hair-edit.json')
asset=Path('src/demos/toy-figure/assets/character.glb');sha=hashlib.sha256(asset.read_bytes()).hexdigest()
assert sha==hashlib.sha256((O/'final/character.glb').read_bytes()).hexdigest()
runs=web['runs'];installed=[r for r in runs if r['candidate']=='installed'];assert len(installed)==2 and all(r['asset_sha256']==sha and not r['errors'] for r in installed)
validators={}
for label,p in [('compressed','final/validator.json'),('decoded','final/validator-decoded.json')]:
 v=read(p);validators[label]={'errors':v['issues']['numErrors'],'warnings':v['issues']['numWarnings'],'infos':v['issues']['numInfos']};assert not v['issues']['numErrors']
verify=(O/'verify-metal.log').read_text();passed=re.search(r'(\d+) passed \(([^\n]+)\)',verify)
summary={'stage':'display2','input_level':400000,'sha256':sha,'glb_bytes':asset.stat().st_size,'glb_MiB':asset.stat().st_size/1048576,'under_15_MiB':asset.stat().st_size<=15*1048576,'triangles':g['triangles'],'neck':neck,'hair':{'removed_components':hair['removed_components'],'removed_triangles':hair['removed_triangles'],'definition':'edge-connected faces, coincident UV seam positions welded for inspection; original principal shell and cap retained'},'textures':c['images'],'compression':{'attribute_preservation':c['attributePreservation'],'topology_preservation':c['topologyPreservation'],'rig_preservation':c['rigPreservation']},'validators':validators,'conditions':web['conditions'],'browser':web['browser'],'performance':installed,'baseline_performance':[r for r in runs if r['candidate']=='baseline'],'candidates':{n:{'MiB':read(n+'/compression.json')['MiB'],'images':read(n+'/compression.json')['images']} for n in ['2048-q75','3072-q75','final']},'verify':{'command':'E2E_PORT=4423 pnpm verify','location':'verify-workspace/ (copied sources and dependencies; all outputs stay under .work)','browser_overlay':'Chrome, ANGLE Metal, workers=4; original repository config unchanged','passed':bool(passed),'tests_passed':int(passed[1]) if passed else None,'duration':passed[2] if passed else None,'log':'verify-metal.log','standard_Chromium_run':{'passed':False,'tests_passed':288,'tests_failed':3,'log':'verify.log','failures':['toy-figure resized canvas uniform','toy-figure iframe canvas uniform','toy-figure reduced motion did not settle under concurrent software rendering']}},'assumptions':['model coordinates retain display normalization to approximately 1m; cut at z=.675m','five neck poses mean rest/left25/right25/up10/down10, with four additional combinations','mobile equivalent means viewport390x844,DPR3,CPU4x on same Mac GPU and local HTTP','retain principal hair shell and cap; do not shave connected hair contour to remove its native irregularities'],'remaining':['actual mobile GPU/network untested','principal hair contour still has native thin or uneven edges; no contour reshaping performed','standard Chromium/software-rendering run has three E2E failures; full verification uses the recorded Chrome/Metal overlay'],'visual_review':{'files':['comparison-recorded-desktop.png','comparison-recorded-face.png','comparison-recorded-body.png','comparison-neck.png','comparison-combinations.png','comparison-hair-up.png','comparison-texture-face.png','comparison-texture-body.png'],'observations':'to be finalized after opening final contact sheets'}}
(O/'metrics.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2));print(json.dumps({k:summary[k] for k in ['glb_MiB','triangles','validators','verify']},ensure_ascii=False,indent=2))
